#!/usr/bin/env bash
# Runtime 模块：pacman 只安装 mise，Node/Python/Go 统一由 mise 管理。

runtime_managed_block() {
  local file="$1" name="$2" content="$3" begin end tmp normalized
  begin="# >>> archdevkit ${name} >>>"
  end="# <<< archdevkit ${name} <<<"
  mkdir -p "$(dirname "${file}")"
  touch "${file}"
  tmp="$(mktemp)"
  awk -v begin="${begin}" -v end="${end}" '
    $0 == begin { skip = 1; next }
    skip && $0 == end { skip = 0; next }
    !skip { print }
  ' "${file}" > "${tmp}"
  normalized="$(mktemp)"
  awk '{ line[NR] = $0 } END { n = NR; while (n > 0 && line[n] == "") n--; for (i = 1; i <= n; i++) print line[i] }' \
    "${tmp}" > "${normalized}"
  mv "${normalized}" "${tmp}"
  if [[ -s "${tmp}" ]]; then
    printf '\n\n' >> "${tmp}"
  fi
  printf '%s\n%s\n%s\n' "${begin}" "${content}" "${end}" >> "${tmp}"
  if cmp -s "${file}" "${tmp}"; then
    rm -f "${tmp}"
    return 0
  fi
  cp -a "${file}" "${file}.bak.$(date +%Y%m%d-%H%M%S)"
  mv "${tmp}" "${file}"
}

remove_legacy_os_init_block() {
  local file="$1" name="$2" begin end tmp
  [[ -f "${file}" ]] || return 0
  begin="# >>> os-init ${name} >>>"
  end="# <<< os-init ${name} <<<"
  grep -Fq "${begin}" "${file}" || return 0
  tmp="$(mktemp)"
  awk -v begin="${begin}" -v end="${end}" '
    $0 == begin { skip = 1; next }
    skip && $0 == end { skip = 0; next }
    !skip { print }
  ' "${file}" > "${tmp}"
  cp -a "${file}" "${file}.bak.$(date +%Y%m%d-%H%M%S)"
  mv "${tmp}" "${file}"
}

remove_legacy_mise_lines() {
  local file="$1" env_file="$2" tmp
  [[ -f "${file}" ]] || return 0
  tmp="$(mktemp)"
  awk -v env_file="${env_file}" '
    $0 == "eval \"$(mise activate bash)\"" { next }
    $0 == "eval \"$(mise activate zsh)\"" { next }
    $0 == "[[ -f \"" env_file "\" ]] && source \"" env_file "\"" { next }
    { print }
  ' "${file}" > "${tmp}"
  if cmp -s "${file}" "${tmp}"; then
    rm -f "${tmp}"
    return 0
  fi
  cp -a "${file}" "${file}.bak.$(date +%Y%m%d-%H%M%S)"
  mv "${tmp}" "${file}"
}

shell_export_line() {
  local name="$1" value="$2"
  [[ -n "${value}" ]] || return 0
  printf 'export %s=%q\n' "${name}" "${value}"
}

write_mise_china_env_file() {
  local env_file="${HOME}/.config/archdevkit/mise-china.env"
  mkdir -p "$(dirname "${env_file}")"
  {
    echo "# Generated by ArchDevKit."
    if [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]]; then
      shell_export_line "NPM_CONFIG_REGISTRY" "${NPM_REGISTRY}"
      shell_export_line "PIP_INDEX_URL" "${PIP_INDEX_URL}"
      shell_export_line "UV_DEFAULT_INDEX" "${UV_DEFAULT_INDEX:-${PIP_INDEX_URL}}"
      shell_export_line "GOPROXY" "${GOPROXY:-https://goproxy.cn,direct}"
    fi
  } > "${env_file}"
  printf '%s' "${env_file}"
}

setup_mise_shell() {
  local env_file zprofile zshrc bash_profile bashrc
  env_file="$(write_mise_china_env_file)"
  remove_legacy_mise_lines "${HOME}/.zshrc" "${env_file}"
  remove_legacy_mise_lines "${HOME}/.bashrc" "${env_file}"
  zprofile="$(cat <<EOF
[[ -f "${env_file}" ]] && source "${env_file}"
if command -v mise >/dev/null 2>&1; then
  eval "\$(mise activate zsh --shims)"
fi
EOF
)"
  zshrc="$(cat <<EOF
[[ -f "${env_file}" ]] && source "${env_file}"
if command -v mise >/dev/null 2>&1; then
  eval "\$(mise activate zsh)"
fi
EOF
)"
  bash_profile="$(cat <<EOF
[[ -f "${env_file}" ]] && source "${env_file}"
if command -v mise >/dev/null 2>&1; then
  eval "\$(mise activate bash --shims)"
fi
EOF
)"
  bashrc="$(cat <<EOF
[[ -f "${env_file}" ]] && source "${env_file}"
if command -v mise >/dev/null 2>&1; then
  eval "\$(mise activate bash)"
fi
EOF
)"
  runtime_managed_block "${HOME}/.zprofile" "mise" "${zprofile}"
  runtime_managed_block "${HOME}/.zshrc" "mise" "${zshrc}"
  runtime_managed_block "${HOME}/.bash_profile" "mise" "${bash_profile}"
  runtime_managed_block "${HOME}/.bashrc" "mise" "${bashrc}"
  remove_legacy_os_init_block "${HOME}/.zshrc" nvm
  remove_legacy_os_init_block "${HOME}/.zshrc" fnm
  remove_legacy_os_init_block "${HOME}/.bashrc" nvm
  remove_legacy_os_init_block "${HOME}/.bashrc" fnm
  log_info "mise shims/activate 已配置到登录与交互式 shell"
}

mise_run_with_china_mirrors() {
  env \
    MISE_NODE_MIRROR_URL="${NODE_MIRROR_URL}" \
    MISE_GO_DOWNLOAD_MIRROR="${GO_DOWNLOAD_MIRROR}" \
    mise "$@"
}

configure_mise() {
  run_cmd mise settings set prefer_offline true
  run_cmd mise settings set node.corepack "$( [[ "${ENABLE_COREPACK:-1}" -eq 1 ]] && echo true || echo false )"
  if [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]]; then
    run_cmd mise settings set node.mirror_url "${NODE_MIRROR_URL}"
    run_cmd mise settings set go.download_mirror "${GO_DOWNLOAD_MIRROR}"
  fi
}

install_mise_runtimes() {
  local tools=("node@${NODE_VERSION}" "python@${PYTHON_VERSION}" "go@${GO_VERSION}")
  log_info "通过 mise 安装全局运行时：${tools[*]}"
  if [[ "${DRY_RUN:-0}" -eq 1 ]]; then
    run_cmd mise use --global "${tools[@]}"
    return 0
  fi
  if [[ "${ENABLE_CHINA_MIRROR:-0}" -eq 1 ]] && ! mise_run_with_china_mirrors use --global "${tools[@]}"; then
    log_warn "国内运行时镜像安装失败，使用官方源重试"
    MISE_NODE_MIRROR_URL="https://nodejs.org/dist/" \
      MISE_GO_DOWNLOAD_MIRROR="https://dl.google.com/go" \
      mise use --global "${tools[@]}"
  elif [[ "${ENABLE_CHINA_MIRROR:-0}" -ne 1 ]]; then
    mise use --global "${tools[@]}"
  fi
}

verify_runtime() {
  [[ "${DRY_RUN:-0}" -eq 1 ]] && return 0
  log_info "验证 mise 管理的 Runtime 版本"
  mise --version
  mise exec -- node --version | grep -Eq "^v${NODE_VERSION}(\\.|$)"
  mise exec -- npm --version >/dev/null
  if [[ "${ENABLE_COREPACK:-1}" -eq 1 ]]; then
    mise exec -- corepack --version >/dev/null
  fi
  mise exec -- python --version | grep -Eq "Python ${PYTHON_VERSION}(\\.|$)"
  mise exec -- python -m pip --version >/dev/null
  mise exec -- go version | grep -Eq "go${GO_VERSION}(\\.|[[:space:]])"
  mise which node >/dev/null
  mise which python >/dev/null
  mise which go >/dev/null
}

install_runtime_env() {
  if is_done "runtime"; then
    log_info "Runtime 环境已处理，跳过"
    return 0
  fi
  log_info "开始安装 Runtime 环境：mise + Node.js ${NODE_VERSION} + Python ${PYTHON_VERSION} + Go ${GO_VERSION}"
  pacman_install mise
  configure_mise
  install_mise_runtimes
  setup_mise_shell
  verify_runtime
  mark_done "runtime"
  log_info "Runtime 环境安装完成"
}

ensure_runtime() {
  if ! is_done "runtime"; then
    install_runtime_env
  fi
}
